create or replace function public.superadmin_iniciar_gravacao(p_pelada_id uuid,p_device_id text,p_started_at timestamptz,p_server_time_offset_ms integer default 0) returns public.recording_sessions language plpgsql security definer set search_path='' as $$ declare v_session public.recording_sessions; begin if not public.is_superadmin() then raise exception 'Acesso negado'; end if; insert into public.pelada_controles(pelada_id,status,team_queue) values(p_pelada_id,'CREATED','{}') on conflict(pelada_id) do nothing; select * into v_session from public.recording_sessions where pelada_id=p_pelada_id and status='RECORDING' order by started_at desc limit 1 for update; if found then return v_session; end if; insert into public.recording_sessions(pelada_id,admin_id,device_id,started_at,server_time_offset_ms,status,upload_status) values(p_pelada_id,auth.uid(),p_device_id,p_started_at,p_server_time_offset_ms,'RECORDING','LOCAL') returning * into v_session; insert into public.pelada_dispositivos(pelada_id,user_id,device_id,mode,status,server_time_offset_ms) values(p_pelada_id,auth.uid(),p_device_id,'CAMERA','ONLINE',p_server_time_offset_ms) on conflict(pelada_id,device_id) do update set user_id=excluded.user_id,mode='CAMERA',status='ONLINE',server_time_offset_ms=excluded.server_time_offset_ms,last_seen_at=now(); update public.pelada_controles set recording_session_id=v_session.id,recording_started_at=p_started_at,device_camera_online=true,updated_at=now() where pelada_id=p_pelada_id; return v_session; end $$;
